<script setup lang="ts">
import { t as uiText } from '@/locales'
import type { InvestmentCurrency } from '@/api/modules/development'
defineProps<{ title: string; currencies: string[]; estimates: InvestmentCurrency[]; actuals: InvestmentCurrency[]; pendingInvestment?:boolean; unit?: { currency: string; manufacturing?: number|null; base?: number|null; dirty?: boolean; calculating?: boolean; taxLabel?: string } }>()
const money=(v:number|null|undefined)=>v==null?uiText('待补'):Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:4})
</script>
<template>
<section class="cost-overview-panel" :aria-label="title"><h3>{{title}}</h3><div class="investment-totals">
<div v-for="currency in currencies" :key="currency" class="currency-totals"><strong>{{currency}}</strong><div><span>{{uiText('预计研发总投入')}}</span><b>{{money(estimates.find(g=>g.currency===currency)?.knownTotal)}}</b><small v-if="estimates.find(g=>g.currency===currency)?.missingCount">{{uiText('已知小计')}} · {{uiText('待补')}} {{estimates.find(g=>g.currency===currency)?.missingCount}} {{uiText('项')}}</small></div><div><span>{{uiText('实际已发生金额')}}</span><b>{{money(actuals.find(g=>g.currency===currency)?.knownTotal)}}</b><small v-if="actuals.find(g=>g.currency===currency)?.missingCount">{{uiText('已登记小计')}} · {{uiText('待补')}} {{actuals.find(g=>g.currency===currency)?.missingCount}} {{uiText('项')}}</small></div></div>
<div class="unit-totals"><strong>{{unit?.currency || '—'}}／{{uiText('件')}}</strong><div><span>{{uiText('单件生产成本')}}</span><b>{{money(unit?.manufacturing)}}</b></div><div><span>{{uiText('单件含摊销成本')}}</span><b>{{money(unit?.base)}}</b><small>{{uiText('成品运输前')}}</small></div></div>
</div><p v-if="pendingInvestment" class="pending">{{uiText('费用有未保存修改，汇总以已保存值为准')}}</p><p v-if="unit?.dirty || unit?.calculating" class="pending">{{uiText(unit.calculating?'正在计算…':'有未保存修改')}}</p><p v-else-if="unit?.taxLabel" class="basis">{{unit.taxLabel}}</p></section>
</template>
